const { GoogleGenerativeAI } = require("@google/generative-ai");
const { buildGeminiParts } = require("./llm-parts-builder.cjs");

/**
 * Cria provider Gemini com streaming de texto incremental.
 * Seguranca: a API key permanece apenas no main process.
 */
function createGeminiProvider(options) {
  const logger = options.logger;
  const fallbackModel = options.modelName || process.env.GEMINI_MODEL || "gemini-3.5-flash";

  async function streamAskResponse(input) {
    const modelName = input.modelId || fallbackModel;
    const genAI = new GoogleGenerativeAI(input.apiKey);
    const model = genAI.getGenerativeModel({ model: modelName });
    const parts = buildGeminiParts(input.ask, input.screenshots, input.audioItems || []);

    logger.info("Starting Gemini streaming request", {
      requestId: input.requestId,
      modelName,
      screenshotCount: (input.screenshots || []).length,
      audioCount: (input.audioItems || []).length
    });

    input.onEvent({
      requestId: input.requestId,
      status: "started",
      createdAtIso: new Date().toISOString()
    });

    const streamResult = await model.generateContentStream(parts);
    let fullText = "";

    for await (const chunk of streamResult.stream) {
      const deltaText = chunk.text();
      if (!deltaText) {
        continue;
      }

      fullText += deltaText;
      input.onEvent({
        requestId: input.requestId,
        status: "chunk",
        deltaText,
        fullText,
        createdAtIso: new Date().toISOString()
      });
    }

    input.onEvent({
      requestId: input.requestId,
      status: "completed",
      fullText,
      createdAtIso: new Date().toISOString()
    });

    logger.info("Gemini streaming request completed", {
      requestId: input.requestId,
      outputLength: fullText.length
    });

    if (input.onUsage) {
      input.onUsage({
        inputTokens: Math.ceil((input.ask || "").length / 4),
        outputTokens: Math.ceil(fullText.length / 4),
        estimated: true
      });
    }
  }

  async function testConnection(apiKey, modelId) {
    const genAI = new GoogleGenerativeAI(apiKey);
    const model = genAI.getGenerativeModel({ model: modelId || fallbackModel });
    const result = await model.generateContent("ping");
    const text = result.response.text();
    if (!text) {
      throw new Error("Resposta vazia do Gemini.");
    }
    return true;
  }

  async function listModels(apiKey) {
    const fetchImpl = options.fetchImpl || fetch;
    const ids = [];
    let pageToken = "";
    for (let page = 0; page < 10; page += 1) {
      const url = new URL("https://generativelanguage.googleapis.com/v1beta/models");
      url.searchParams.set("pageSize", "1000");
      if (pageToken) url.searchParams.set("pageToken", pageToken);
      const response = await fetchImpl(url, { headers: { "x-goog-api-key": apiKey } });
      if (!response.ok) {
        const errText = await response.text();
        throw new Error(`HTTP ${response.status} ao listar modelos Gemini: ${errText.slice(0, 200)}`);
      }
      const body = await response.json();
      for (const model of body.models || []) {
        const methods = model.supportedGenerationMethods || [];
        if (model.name && (!methods.length || methods.includes("generateContent"))) {
          ids.push(String(model.name).replace(/^models\//, ""));
        }
      }
      pageToken = body.nextPageToken || "";
      if (!pageToken) break;
    }
    return ids;
  }

  return {
    streamAskResponse,
    testConnection,
    listModels
  };
}

module.exports = {
  createGeminiProvider
};
